<?php
namespace OpenLMS\Controllers;

use OpenLMS\Core\Auth;
use OpenLMS\Core\Csrf;
use OpenLMS\Core\Database;
use OpenLMS\Policies\CoursePolicy;
use OpenLMS\Services\UploadService;

trait ProjectListTrait
{
    public static function index(): void
    {
        require_feature('projects');Auth::requireAuth();$u=Auth::user();$pdo=Database::connection();$manage=Auth::can('projects.manage');$error=null;$message=null;
        if($_SERVER['REQUEST_METHOD']==='POST'&&$manage){if(!Csrf::validate($_POST['_csrf']??null))$error='Security token expired.';else try{$courseId=(int)($_POST['course_id']??0);$course=self::course($courseId);if(!$course||!CoursePolicy::canManage($course,$u))throw new \RuntimeException('Course access denied.');$title=trim((string)($_POST['title']??''));if($title==='')throw new \RuntimeException('Project title is required.');$start=utc_datetime_from_input($_POST['starts_at']??null);$deadline=utc_datetime_from_input($_POST['deadline_at']??null);if($start&&$deadline&&$deadline<=$start)throw new \RuntimeException('Deadline must be after start.');$type=in_array($_POST['project_type']??'individual',['individual','group'],true)?$_POST['project_type']:'individual';$late=in_array($_POST['late_policy']??'reject',['reject','allow'],true)?$_POST['late_policy']:'reject';$extensions=implode(',',array_intersect(parse_csv_list((string)($_POST['allowed_extensions']??'')),['pdf','doc','docx','ppt','pptx','jpg','jpeg','png','webp','zip']));if($extensions==='')throw new \RuntimeException('Choose at least one approved file extension.');$max=max(1,min(25,(int)($_POST['max_upload_mb']??10)))*1024*1024;$now=gmdate('Y-m-d H:i:s');$pdo->prepare("INSERT INTO projects (course_id,title,instructions,project_type,starts_at,deadline_at,max_upload_bytes,status,created_at,allowed_extensions,allow_multiple_files,resubmission_allowed,late_policy,max_marks,rubric_json,updated_at) VALUES (?,?,?,?,?,?,?,'draft',?,?,?,?,?,?,?,?)")->execute([$courseId,$title,trim((string)($_POST['instructions']??'')),$type,$start,$deadline,$max,$now,$extensions,bool_post('allow_multiple_files'),bool_post('resubmission_allowed'),$late,max(0,(float)($_POST['max_marks']??100)),trim((string)($_POST['rubric_json']??'')),$now]);$message='Project created.';}catch(\Throwable $e){$error=$e instanceof \RuntimeException?$e->getMessage():'Unable to create project.';}}
        $rows=self::projectsForUser($u);$courses=$manage?self::manageableCourses($u):[];ob_start();?><div class="page-head"><div><h1>Projects & assignments</h1><p class="muted">Deadlines, private versioned submissions, group ownership, grading and feedback.</p></div></div><?php if($message):?><div class="alert alert-success"><?=e($message)?></div><?php endif;?><?php if($error):?><div class="alert alert-danger"><?=e($error)?></div><?php endif;?><?php if($manage):?><section class="card"><h2>Create project</h2><form method="post"><input type="hidden" name="_csrf" value="<?=e(Csrf::token())?>"><label>Course<select name="course_id" required><?php foreach($courses as $c):?><option value="<?=(int)$c['id']?>"><?=e($c['title'])?></option><?php endforeach;?></select></label><label>Title<input name="title" required></label><label>Instructions<textarea name="instructions" rows="4"></textarea></label><div class="form-row"><label>Type<select name="project_type"><option value="individual">Individual</option><option value="group">Group</option></select></label><label>Maximum marks<input type="number" name="max_marks" min="0" step="0.25" value="100"></label></div><div class="form-row"><label>Starts<input type="datetime-local" name="starts_at"></label><label>Deadline<input type="datetime-local" name="deadline_at"></label></div><div class="form-row"><label>Max upload MB<input type="number" name="max_upload_mb" min="1" max="25" value="10"></label><label>Late policy<select name="late_policy"><option value="reject">Reject after deadline</option><option value="allow">Allow and mark late</option></select></label></div><label>Allowed extensions<input name="allowed_extensions" value="pdf,doc,docx,ppt,pptx,jpg,jpeg,png,webp,zip"></label><label class="check-row"><input type="checkbox" name="allow_multiple_files" checked> Allow multiple files</label><label class="check-row"><input type="checkbox" name="resubmission_allowed" checked> Allow resubmission versions</label><label>Rubric JSON / notes<textarea name="rubric_json" placeholder='{"Quality":40,"Accuracy":60}'></textarea></label><button class="btn btn-primary">Create draft</button></form></section><?php endif;?><div class="card-grid"><?php foreach($rows as $p):?><article class="card"><span class="badge"><?=e($p['status'])?></span><h2><?=e($p['title'])?></h2><p class="muted"><?=e($p['course_title'])?> · <?=e($p['project_type'])?></p><p><?=e(mb_strimwidth((string)$p['instructions'],0,180,'…'))?></p><p class="muted">Deadline: <?=e($p['deadline_at']??'No deadline')?> · Submissions: <?=(int)$p['submission_count']?></p><a class="btn" href="<?=e(app_url('?r=project&id='.(int)$p['id']))?>">Open project</a></article><?php endforeach;?><?php if(!$rows):?><div class="card empty-state">No projects available.</div><?php endif;?></div><?php render_page('Projects',ob_get_clean());
    }
    public static function download(): void
    {
        require_feature('projects');Auth::requireAuth();$u=Auth::user();$pdo=Database::connection();$st=$pdo->prepare('SELECT sf.*,ps.user_id,ps.group_id,p.id project_id,p.course_id,c.teacher_id,c.status course_status,s.status subject_status FROM submission_files sf JOIN project_submissions ps ON ps.id=sf.submission_id JOIN projects p ON p.id=ps.project_id JOIN courses c ON c.id=p.course_id JOIN subjects s ON s.id=c.subject_id WHERE sf.id=?');$st->execute([(int)($_GET['id']??0)]);$f=$st->fetch();if(!$f){http_response_code(404);return;}$course=['id'=>$f['course_id'],'teacher_id'=>$f['teacher_id'],'status'=>$f['course_status'],'subject_status'=>$f['subject_status']];$allowed=CoursePolicy::canManage($course,$u)||(int)$f['user_id']===(int)$u['id']||($f['group_id']&&self::groupMember((int)$f['group_id'],(int)$u['id']));if(!$allowed){http_response_code(404);return;}$path=UploadService::resolveStoredPath((string)$f['stored_name']);if(!$path||!is_file($path)){http_response_code(404);return;}header('Content-Type: '.(string)$f['mime_type']);header('Content-Length: '.filesize($path));header('Content-Disposition: attachment; filename="'.str_replace(['"','\r','\n'],'_',basename((string)$f['original_name'])).'"');header('X-Content-Type-Options: nosniff');readfile($path);exit;
    }
}
